    @Test
    void aPercentageDiscountRoundsHalfUpToAMinorUnit() {
        try (var shop = new AnnotationConfigApplicationContext(ShopConfig.class)) {
            OrderFacade orders = shop.getBean(OrderFacade.class);
            Instant at = Instant.parse("2026-10-01T10:00:00Z");

            String half = orders.place("c-1", Money.pln(100), at);
            orders.applyDiscount(half, "0.5");
            assertEquals(Money.pln(99), orders.summary(half).total());

            String fractional = orders.place("c-1", Money.pln(1000), at);
            orders.applyDiscount(fractional, "12.5");
            assertEquals(Money.pln(875), orders.summary(fractional).total());

            String roundsUp = orders.place("c-1", Money.pln(1001), at);
            orders.applyDiscount(roundsUp, "12.5");
            assertEquals(Money.pln(876), orders.summary(roundsUp).total());
        }
    }

    @Test
    void anInvalidDiscountIsRejected() {
        try (var shop = new AnnotationConfigApplicationContext(ShopConfig.class)) {
            OrderFacade orders = shop.getBean(OrderFacade.class);
            String id = orders.place("c-1", Money.pln(1000), Instant.parse("2026-10-01T10:00:00Z"));

            assertThrows(IllegalArgumentException.class, () -> orders.applyDiscount(id, "abc"));
            assertThrows(IllegalArgumentException.class, () -> orders.applyDiscount(id, "-1"));
            assertThrows(IllegalArgumentException.class, () -> orders.applyDiscount(id, "100.01"));
            assertThrows(IllegalArgumentException.class, () -> orders.applyDiscount(id, null));
            assertEquals(Money.pln(1000), orders.summary(id).total());
        }
    }
